#!/usr/bin/env python3
"""Writes the byte tables of Specs/analysis_rules.t27 (the call analysis agent) from the readable lists below.

The spec carries one generated block between
    ; >>> generated by Specs/tables/analysis_tables.py ...
    ; <<< generated
with named row indexes and the rows as packed UTF-8 bytes with offsets and lengths (t27 has no string
arrays that reach C). Run by Specs/generate.sh; edit the lists here, not the spec. The table layout is
ponte_tables.table, so every spec's tables read the same way.

- AN_ROW: the providers (their IDs, default base URLs and models, in AN_PROVIDER_* order), the request path,
  the Keychain service prefix, the Authorization scheme, the URL schemes the base URL may start with, and the
  report file name's prefix and suffix.
- AN_FX: the texts the spec's own tests use.
"""
import pathlib
import re
import sys

sys.dont_write_bytecode = True
from ponte_tables import table  # noqa: E402  (same folder; generate.sh runs this file directly)

SPECS = pathlib.Path(__file__).resolve().parents[1]
BEGIN = "; >>> generated by Specs/tables/analysis_tables.py -- edit the lists there, not here"

# In AN_PROVIDER_* order: 0 Z.ai (GLM), 1 DeepSeek, 2 custom (an OpenAI-compatible service the owner names).
# (id, default base URL, default model). The id names the Keychain item and the stored settings.
PROVIDERS = [
    ("zai", "https://api.z.ai/api/paas/v4", "glm-4.5-flash"),
    ("deepseek", "https://api.deepseek.com", "deepseek-flash"),
    ("custom", "", ""),
]

WORDS = [
    ("PATH", "/chat/completions"),            # appended to the base URL: <base>/chat/completions
    ("KEYCHAIN_PREFIX", "ponte-analysis-"),   # Keychain generic password service: ponte-analysis-<id>
    ("BEARER", "Bearer "),                    # Authorization: Bearer <key>
    ("HTTPS", "https://"),
    ("HTTP", "http://"),
    ("REPORT_PREFIX", "Ponte-report-"),       # Ponte-report-YYYY-MM-DD-HHmm[-N].txt
    ("REPORT_SUFFIX", ".txt"),
]

FIXTURES = [
    ("ZAI_BASE", "https://api.z.ai/api/paas/v4"),
    ("ZAI_SLASH", "https://api.z.ai/api/paas/v4//"),
    ("ZAI_ENDPOINT", "https://api.z.ai/api/paas/v4/chat/completions"),
    ("ZAI_ENDPOINT_SLASH", "https://api.z.ai/api/paas/v4/chat/completions/"),
    ("DEEPSEEK_ENDPOINT", "https://api.deepseek.com/chat/completions"),
    ("LOCAL", "http://localhost:11434/v1"),
    ("LOCAL_ENDPOINT", "http://localhost:11434/v1/chat/completions"),
    ("UPPER", "HTTPS://API.DEEPSEEK.COM"),
    ("FTP", "ftp://example.com"),
    ("SCHEME_ONLY", "https://"),
    ("SCHEME_SLASH", "https:///"),
    ("SPACE", "https://api.z.ai/a b"),
    ("NO_SCHEME", "api.z.ai/api/paas/v4"),
    ("EMPTY", ""),
    ("SLASH", "/"),
    ("KEY_ZAI", "ponte-analysis-zai"),
    ("KEY_CUSTOM", "ponte-analysis-custom"),
    ("REPORT_1405", "Ponte-report-2026-10-13-1405.txt"),
    ("REPORT_2359_2", "Ponte-report-2026-01-02-2359-2.txt"),
    ("REPORT_0000_12", "Ponte-report-2027-12-31-0000-12.txt"),
    ("CYRILLIC", "https://пример.рф/v1"),
]


def write_block(spec_name, lines):
    spec = SPECS / spec_name
    source = spec.read_text()
    block = "\n".join([BEGIN] + lines + ["; <<< generated"])
    source, n = re.subn(re.escape(BEGIN) + r".*?; <<< generated", lambda _: block, source, flags=re.S)
    if n != 1:
        sys.exit(f"{spec_name}: generated block not found")
    if any(ord(ch) > 127 for ch in source):
        sys.exit(f"{spec_name}: not ASCII after generation")
    if spec.read_text() != source:
        spec.write_text(source)


def main():
    rows = []
    first_id = len(rows)
    rows += [(f"ID_{i}", pid) for i, (pid, _, _) in enumerate(PROVIDERS)]
    first_base = len(rows)
    rows += [(f"BASE_{i}", base) for i, (_, base, _) in enumerate(PROVIDERS)]
    first_model = len(rows)
    rows += [(f"MODEL_{i}", model) for i, (_, _, model) in enumerate(PROVIDERS)]
    rows += WORDS
    constants = [
        f"pub const AN_ROW_FIRST_ID : i64 = {first_id};",
        f"pub const AN_ROW_FIRST_BASE : i64 = {first_base};",
        f"pub const AN_ROW_FIRST_MODEL : i64 = {first_model};",
    ]
    lines = table("AN_ROW", "Rows: provider IDs, default base URLs and models (AN_PROVIDER_* order), then words",
                  rows, constants)
    lines += table("AN_FX", "Texts for the tests", FIXTURES, [])
    write_block("analysis_rules.t27", lines)
    print(f"analysis tables: {len(rows)} rows, {len(FIXTURES)} fixtures")


if __name__ == "__main__":
    main()
